def point_triangle_candidates(point,triangle):
 edge_first=triangle[1]-triangle[0];edge_second=triangle[2]-triangle[0]
 normal=np.cross(edge_first,edge_second)
 projection=point-normal*np.dot(point-triangle[0],normal)/np.dot(normal,normal)
 coefficients=np.linalg.lstsq(np.column_stack((edge_first,edge_second)),projection-triangle[0],rcond=None)[0]
 candidates=[]
 if min(coefficients)>=-1e-12 and sum(coefficients)<=1+1e-12:candidates.append(projection)
 for index in range(3):
  start=triangle[index];edge=triangle[(index+1)%3]-start
  candidates.append(start+np.clip(np.dot(point-start,edge)/np.dot(edge,edge),0,1)*edge)
 return candidates
def edge_candidates(start09,end09,start03,end03):
